/**
 * Entry point for the Notifications screen. Connects [UserNotificationsViewModel] to
 * [UserNotificationsContent].
 *
 * @param profileId the current entrant's profile ID, used to show only their notifications.
 * @param onBack called when the back button is tapped.
 * @param onOpenNotif called when a notification is tapped, with its type, reservation ID, and
 *   lottery ID, so the caller can navigate to the right screen.
 * @param viewModel the screen's ViewModel; can be replaced for testing.
 */
@Composable
fun UserNotificationsScreen(
    profileId: String,
    onBack: () -> Unit,
    onOpenNotif: (notifType: String, reservationId: String, lotteryId: String) -> Unit,
    viewModel: UserNotificationsViewModel = viewModel()
){

    UserNotificationsContent(
        onBack = onBack,
        onViewed = { notificationId -> viewModel.markViewed(notificationId, profileId)},
        onOpenNotif = onOpenNotif,
        profileId = profileId,
        viewModel = viewModel
    )
}

/**
 * The Notifications screen layout: header, search bar, and the list of notification cards.
 * Shows all of the entrant's notifications until something is typed, then updates the list
 * as the search text changes.
 *
 * @param onBack called when the back button is tapped.
 * @param onViewed called with a notification's ID when it is tapped, to mark it viewed.
 * @param onOpenNotif called with a notification's type, reservation ID, and lottery ID when tapped.
 * @param profileId the current entrant's profile ID, used when searching.
 * @param viewModel provides the search results and runs searches.
 */
@Composable
fun UserNotificationsContent(
    onBack: () -> Unit,
    onViewed: (String) -> Unit,
    onOpenNotif: (notifType: String, reservationId: String, lotteryId: String) -> Unit,
    profileId: String,
    viewModel: UserNotificationsViewModel
) {
    var search by remember { mutableStateOf("") }

    // From Claude Opus 5.5, 2026/11/23
    // "How can I make it automatically display all the notifications when nothing has
    // been searched yet? Minimal fix please"

    LaunchedEffect(viewModel.allNotifications.size) {
        viewModel.doSearch(search, profileId)
    }

    Scaffold(modifier = Modifier) { padding ->
        Column(
            verticalArrangement = Arrangement.spacedBy(12.dp),
            modifier = Modifier
                .fillMaxSize()
                .padding(padding)
                .padding(horizontal = 16.dp, vertical = 8.dp)
        ) {
            BackButtonAndHeaderScreenComponent(
                title = "Notifications",
                subHeader = "Notifications you've recieved",
                onBack = onBack
            )

            //search notifications
            OutlinedTextField(
                value = search,
                onValueChange = {
                    search = it
                    viewModel.doSearch(it, profileId)
                },
                placeholder = { Text("Search Notifications") },
                singleLine = true,
                shape = MaterialTheme.shapes.medium,
                modifier = Modifier.fillMaxWidth()
            )

            Spacer(Modifier.height(8.dp))
            //if no notifications
            if (viewModel._searchResults.isEmpty()) {
                Box(
                    Modifier
                        .fillMaxSize()
                        .weight(1f),
                    contentAlignment = Alignment.Center
                ) {
                    Text(
                        text = "No Notifications",
                        style = MaterialTheme.typography.bodyLarge,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            } else {
                LazyColumn(
                    modifier = Modifier
                        .fillMaxWidth()
                        .weight(1f),
                    contentPadding = PaddingValues(16.dp),
                    verticalArrangement = Arrangement.spacedBy(12.dp)
                ) {
                    items(viewModel._searchResults, key = { it.id }) { notification ->
                        NotificationCard(
                            notification = notification,
                            isViewed = profileId in notification.viewedBy,
                            onClick = {
                                onViewed(notification.id)
                                onOpenNotif(notification.type, notification.reservationId, notification.lotteryId)
                            },
                        )
                    }
                }
            }
        }
    }
}


/**
 * One notification card showing the subject, time sent, and message. Shown greyed out once
 * it has been viewed.
 *
 * @param notification the notification to display.
 * @param isViewed whether the notification has already been viewed.
 * @param onClick called when the card is tapped.
 */
@Composable
private fun NotificationCard(
    notification: Notifications,
    isViewed: Boolean,
    onClick: () -> Unit
) {
    Surface(
        onClick = onClick,
        color = if(isViewed){ MaterialTheme.colorScheme.surfaceVariant} else{MaterialTheme.colorScheme.surface},
        border = BorderStroke(1.dp, MaterialTheme.colorScheme.outlineVariant),
        shape = MaterialTheme.shapes.medium,
        modifier = Modifier
            .fillMaxWidth()
    ) {
        Column(Modifier.padding(16.dp)) {
            Row(verticalAlignment = Alignment.Top) {
                // notification details
                Column(Modifier.weight(1f)) {
                    Text(
                        notification.subject,
                        style = MaterialTheme.typography.titleMedium,
                        fontWeight = FontWeight.Bold,
                    )
                    Text(
                        text = appDateFormat("MMM d, yyyy h:mm a").format(
                            notification.timestamp
                        ),
                        style = MaterialTheme.typography.bodySmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                    Text(
                        notification.message,
                        style = MaterialTheme.typography.bodyMedium,
                    )
                }
            }
        }
    }
}
